/**
 * Member-count closed form (documented derivation)
 * ------------------------------------------------
 * For a Pratt through-truss with N panels (N even, here default N = 6):
 *
 *   - bottom chord nodes: b0..bN          (N + 1 nodes)
 *   - top chord nodes:    t1..t(N-1)      (N - 1 nodes)
 *
 * Members:
 *   - bottom chords: one per panel            -> N
 *   - top chords: chain over t1..t(N-1)       -> N - 2
 *   - verticals at interior panel points      -> N - 1
 *     (bottom points b1..b(N-1), each tied to its top node)
 *   - diagonals sloping toward midspan        -> N
 *     (left half rises toward center: b(i)-t(i+1) for i < N/2,
 *      right half mirrors:        b(i)-t(i-1) for i > N/2;
 *      this includes the two inclined end posts at b0 and bN)
 *
 * Total = N + (N - 2) + (N - 1) + N = 4N - 3.
 * For panels = 6: 4*6 - 3 = 21 members.
 */

/**
 * Design a Pratt truss.
 * @param {{panels?: number, panelLen?: number, height?: number}} opts
 * @returns {{nodes: Array<{label: string, position: THREE.Vector3}>, members: Array<{a: string, b: string, type: string}>}}
 */
export function designTruss({ panels = 6, panelLen = 4, height = 3 } = {}) {
  if (!Number.isInteger(panels) || panels < 2 || panels % 2 !== 0) {
    throw new Error('panels must be an even integer >= 2');
  }

  const nodes = [];
  const byLabel = new Map();
  const addNode = (label, x, y) => {
    const node = { label, position: new THREE.Vector3(x, y, 0) };
    nodes.push(node);
    byLabel.set(label, node);
  };

  // Bottom chord: b0..bN along y = 0
  for (let i = 0; i <= panels; i++) addNode(`b${i}`, i * panelLen, 0);
  // Top chord: t1..t(N-1) along y = height
  for (let i = 1; i <= panels - 1; i++) addNode(`t${i}`, i * panelLen, height);

  const members = [];
  const half = panels / 2;

  // Bottom chords
  for (let i = 0; i < panels; i++) {
    members.push({ a: `b${i}`, b: `b${i + 1}`, type: 'bottom' });
  }
  // Top chords
  for (let i = 1; i <= panels - 2; i++) {
    members.push({ a: `t${i}`, b: `t${i + 1}`, type: 'top' });
  }
  // Verticals at every interior panel point
  for (let i = 1; i <= panels - 1; i++) {
    members.push({ a: `b${i}`, b: `t${i}`, type: 'vertical' });
  }
  // Diagonals sloping toward midspan (inclined end posts included)
  for (let i = 0; i < panels; i++) {
    if (i < half) {
      members.push({ a: `b${i}`, b: `t${i + 1}`, type: 'diagonal' }); // rises toward center
    } else {
      members.push({ a: `b${i}`, b: `t${i - 1}`, type: 'diagonal' }); // mirror image
    }
  }

  return { nodes, members };
}

/**
 * Build the space-frame mesh: one cylinder per member, oriented and sized
 * between its two node endpoints.
 * @param {{nodes: Array<{label: string, position: THREE.Vector3}>, members: Array<{a: string, b: string}>}} design
 * @returns {THREE.Group} group whose children are the member cylinders,
 *   each carrying userData {a, b, type}
 */
export function buildTruss(design) {
  const byLabel = new Map(design.nodes.map((n) => [n.label, n.position]));
  const group = new THREE.Group();
  group.name = 'truss';

  const up = new THREE.Vector3(0, 1, 0);
  const dir = new THREE.Vector3();

  for (const m of design.members) {
    const pa = byLabel.get(m.a);
    const pb = byLabel.get(m.b);
    if (!pa || !pb) throw new Error(`unknown node label in member ${m.a}-${m.b}`);

    const length = pa.distanceTo(pb);
    dir.subVectors(pb, pa).normalize();

    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 1, 12));
    mesh.scale.set(1, length, 1);                 // unit cylinder stretched to span
    mesh.quaternion.setFromUnitVectors(up, dir);  // align local +Y with member axis
    mesh.position.copy(pa).addScaledVector(dir, length / 2); // midpoint
    mesh.userData = { a: m.a, b: m.b, type: m.type };
    mesh.updateMatrixWorld(true);

    group.add(mesh);
  }

  return group;
}
