result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/truss.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { designTruss, buildTruss } from '../src/truss.js';

/**
 * Closed-form member total for a Pratt truss with N panels:
 *   bottom chords (N) + top chords (N-2) + verticals (N-1) + diagonals (N)
 *   = 4N - 3. For N = 6 that is 21.
 */
const EXPECTED_MEMBERS_6_PANELS = 21;

/** Union-Find (disjoint set) with path compression + union by size. */
class UnionFind {
  constructor() {
    this.parent = new Map();
    this.size = new Map();
  }
  find(x) {
    if (!this.parent.has(x)) {
      this.parent.set(x, x);
      this.size.set(x, 1);
    }
    let root = x;
    while (this.parent.get(root) !== root) root = this.parent.get(root);
    while (this.parent.get(x) !== root) {
      const next = this.parent.get(x);
      this.parent.set(x, root);
      x = next;
    }
    return root;
  }
  union(a, b) {
    const ra = this.find(a);
    const rb = this.find(b);
    if (ra === rb) return false;
    if (this.size.get(ra) < this.size.get(rb)) [ra, rb] = [rb, ra];
    this.parent.set(rb, ra);
    this.size.set(ra, this.size.get(ra) + this.size.get(rb));
    return true;
  }
}

/** Axis-aligned bounding box extent of a mesh measured along |dir|. */
function boxExtentAlongAxis(mesh, dirAbs) {
  const box = new THREE.Box3().setFromObject(mesh);
  const size = new THREE.Vector3();
  box.getSize(size);
  return dirAbs.x * size.x + dirAbs.y * size.y + dirAbs.z * size.z;
}

describe('designTruss', () => {
  const design = designTrust6();

  function designTrust6() {
    return designTrust();
  }
  function designTrust() {
    return designTrussSafe();
  }
  function designTrussSafe() {
    return designTruss({ panels: 6, panelLen: 4, height: 3 });
  }

  it('labels nodes as b0..b6 and t1..t5', () => {
    const labels = design.nodes.map((n) => n.label).sort();
    expect(labels).toEqual(
      ['b0', 'b1', 'b2', 'b3', 'b4', 'b5', 'b6', 't1', 't2', 't3', 't4', 't5'].sort()
    );
  });

  it('member count matches closed-form total 4*6 - 3 = 21', () => {
    expect(design.members.length).toBe(EXPECTED_MEMBERS_6_PANELS);
  });

  it('contains no duplicate members', () => {
    const keys = design.members.map((m) =>
      [m.a, m.b].sort().join('|')
    );
    expect(new Set(keys).size).toBe(keys.length);
  });

  it('has the expected Pratt member breakdown', () => {
    const counts = { bottom: 0, top: 0, vertical: 0, diagonal: 0 };
    for (const m of design.members) counts[m.type]++;
    expect(counts).toEqual({ bottom: 6, top: 4, vertical: 5, diagonal: 6 });
  });

  it('diagonals slope toward midspan', () => {
    const pos = new Map(design.nodes.map((n) => [n.label, n.position]));
    const halfX = 3 * 4; // panels/2 * panelLen
    for (const m of design.members) {
      if (m.type !== 'diagonal') continue;
      const low = pos.get(m.a).y <= pos.get(m.b).y ? m.a : m.b;
      const high = low === m.a ? m.b : m.a;
      const highX = pos.get(high).x;
      expect(Math.abs(highX - halfX)).toBeLessThan(Math.abs(pos.get(low).x - halfX));
    }
  });
});

describe('buildTruss', () => {
  const design = designTruss({ panels: 6, panelLen: 4, height: 3 });
  const group = buildTruss(design);
  const pos = new Map(design.nodes.map((n) => [n.label, n.position]));

  it('creates exactly one cylinder mesh per member', () => {
    expect(group.children.length).toBe(design.members.length);
    for (const child of group.children) {
      expect(child).toBeInstanceOf(THREE.Mesh);
      expect(child.geometry.type).toBe('CylinderGeometry');
    }
  });

  it("every member's mesh length equals its endpoint distance within 1e-6", () => {
    for (const mesh of group.children) {
      const { a, b } = mesh.userData;
      const expected = pos.get(a).distanceTo(pos.get(b));
      const dir = new THREE.Vector3().subVectors(pos.get(b), pos.get(a)).normalize();
      const actual = boxExtentAlongAxis(mesh, new THREE.Vector3(Math.abs(dir.x), Math.abs(dir.y), Math.abs(dir.z)));
      expect(Math.abs(actual - expected)).toBeLessThanOrEqual(1e-6);
      // cross-check via endpoints of the oriented geometry
      const p0 = new THREE.Vector3(0, -0.5, 0).applyMatrix4(mesh.matrixWorld);
      const p1 = new THREE.Vector3(0, 0.5, 0).applyMatrix4(mesh.matrixWorld);
      expect(p0.distanceTo(p1)).toBeCloseTo(expected, 6);
    }
  });

  it('structure graph is connected (union-find over members)', () => {
    const uf = new UnionFind();
    for (const m of design.members) uf.union(m.a, m.b);
    const roots = new Set(design.nodes.map((n) => uf.find(n.label)));
    expect(roots.size).toBe(1);
  });

  it('verticals are perfectly vertical (|dx|,|dz| < 1e-9)', () => {
    for (const m of design.members) {
      if (m.type !== 'vertical') continue;
      const d = new THREE.Vector3().subVectors(pos.get(m.b), pos.get(m.a));
      expect(Math.abs(d.x)).toBeLessThan(1e-9);
      expect(Math.abs(d.z)).toBeLessThan(1e-9);
      expect(d.y).not.toBe(0);
    }
  });

  it('chords are perfectly horizontal (|dy| < 1e-9)', () => {
    for (const m of design.members) {
      if (m.type !== 'bottom' && m.type !== 'top') continue;
      const d = new THREE.Vector3().subVectors(pos.get(m.b), pos.get(m.a));
      expect(Math.abs(d.y)).toBeLessThan(1e-9);
    }
  });
});
